import attr

from typing import Optional
from taf.config.testline.airscale import CommonUnit
from taf.config.testline.gnb.networkaddress import NetworkAddress
from taf.config.testline.testpc import TestPc


@attr.s(cmp=False)
class IPHY(object):
    """
    Class which represents simulated RMOD (IPHY)

    :param int ip_set: IP set (1-100) to which IPHY belongs along with the hardware MAC address
    :param NetworkAddress trs_ip_addr: IP address of TRS interface connected via SMOD EIF port for communication with
                                       simulated UE/core
    :param CommonUnit common_unit: Common Unit object used for RMOD
    :param TestPc test_pc: PC or VM connected with certain IPHY
    """
    ip_set = attr.ib(type=int, validator=attr.validators.in_(range(1, 101)))
    trs_ip_addr = attr.ib(type=NetworkAddress)
    common_unit = attr.ib(type=CommonUnit)
    test_pc = attr.ib(default=None, type=TestPc)

@attr.s(cmp=False)
class RUsim(object):
    """
    Class which represents simulated RMOD (APoDocker) as docker on specified PC.

    :param TestPc test_pc: PC or VM where docker is set up.
    :param interface str: VM network interface that specified docker uses
    """
    test_pc = attr.ib(default=None, type=TestPc)
    interface = attr.ib(default=None, type=Optional[str])
